 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    cells4 = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 4]
    cells6 = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6]
    if not cells4 or not cells6:
        return out
    r0, r1 = min(r for r, c in cells4), max(r for r, c in cells4)
    c0, c1 = min(c for r, c in cells4), max(c for r, c in cells4)
    # The arrow marker indicates the side toward which to reflect the source object.
    # Downward markers produce a vertical reflection immediately below the source.
    six_rows = [r for r, c in cells6]
    six_cols = [c for r, c in cells6]
    # Determine arrow orientation from the broad row (the arrowhead) versus its stem.
    row_counts = {r: sum(1 for rr, c in cells6 if rr == r) for r in set(six_rows)}
    col_counts = {c: sum(1 for r, cc in cells6 if cc == c) for c in set(six_cols)}
    if max(row_counts.values()) >= max(col_counts.values()):
        head_row = min(row_counts, key=lambda r: (-row_counts[r], r))
        down = head_row == max(six_rows)
    else:
        head_col = min(col_counts, key=lambda c: (-col_counts[c], c))
        down = head_col == min(six_cols)  # vertical stem with horizontal arrowhead
    if down:
        # Clear the marker, then append the vertically flipped source pattern below it.
        for r, c in cells6:
            out[r][c] = 0
        for r, c in cells4:
            nr = r0 + r1 + 1 - r
            if 0 <= nr < h:
                out[nr][c] = 4
    else:
        # Up-arrow case: mirror horizontally to the right of the source.
        for r, c in cells6:
            out[r][c] = 0
        for r, c in cells4:
            nc = c0 + c1 + 1 - c
            if 0 <= nc < w:
                out[r][nc] = 4
    return out
